window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-442e2fefebc19b75"]={"versions": [{"id": "FIG-442e2fefebc19b75", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsszenario mit Interaktionsrahmen <code>loop</code>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R23-11, Spezifikation <code>AUTOSAR_AP_EXP_SWArchitecture</code>, Kapitel 11 (Platform Health Management, PHM).\n</li><li><strong>Technischer Zweck:</strong> Darstellung des zyklischen Basismechanismus zur Überwachung der Plattform- und Applikationsintegrität sowie der abgeleiteten Watchdog-Bedienung. Das PHM dient als zentrale Instanz zur Bündelung aller Überwachungsergebnisse vor dem Hardware-/System-Watchdog-Trigger.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>«aapFunctionalCluster» :Platform Health Management</code>:</strong>\n<ul class=\"fig-list\"><li>Instanz des funktionalen Clusters PHM der Adaptive Platform.\n</li><li>Verantwortlich für die Aggregation und Auswertung aller konfigurierten Überwachungsarten (<em>Alive Supervision</em>, <em>Deadline Supervision</em>, <em>Logical Supervision</em>).\n</li></ul>\n</li><li><strong><code>:Watchdog</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrahierte Zielentität (z. B. Watchdog-Daemon, OS-Watchdog-Service oder Hardware-Watchdog-Treiber).\n</li></ul>\n</li><li><strong>Aufgerufene Operationen / Schnittstellen:</strong>\n<ul class=\"fig-list\"><li><code>checkSupervisions()</code>: PHM-interne synchrone Methode (Self-Call) zur periodischen Auswertung aller aktiven Überwachungsmetriken und Checkpoint-Zustände.\n</li><li><code>AliveNotification()</code>: Ausgehender Methodenaufruf vom PHM an den Watchdog zur Bestätigung der Systemlebensfähigkeit (<em>Watchdog Refresh / Kick</em>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Zyklus (<code>loop</code>-Block):</strong> Läuft deterministisch in einer Endlosschleife, getaktet durch die konfigurierte Zykluszeit der PHM-Hauptverarbeitungsaufgabe.\n</li></ul>\n<ol class=\"fig-list\"><li><strong>Zustandsevaluierung:</strong> Das PHM führt intern <code>checkSupervisions()</code> aus. Hierbei werden alle empfangenen Checkpoint-Meldungen, Alive-Zähler, Ausführungsreihenfolgen und Latenzzeiten der überwachten Prozesse gegen die im Manifest hinterlegten Schwellwerte validiert.\n</li><li><strong>Watchdog-Triggern:</strong> Bei intaktem Gesamtzustand (<em>Supervision Status: OK</em>) setzt das PHM den Aufruf <code>AliveNotification()</code> an die Entität <code>:Watchdog</code> ab, um einen Timeout/Reset des Watchdogs zu verhindern.\n</li></ol>\n<ul class=\"fig-list\"><li><strong>Fehlerpfad (implizit/Abbruchbedingung):</strong> Ergibt <code>checkSupervisions()</code> einen unzulässigen Status (z. B. Deadline-Verletzung, Alive-Counter-Diskrepanz) und greift keine rein lokale Recovery Action, wird <code>AliveNotification()</code> unterdrückt. Dies führt zum gezielten Ablauf des Watchdogs und initiiert den plattformweiten Hardware-/System-Reset.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Architektur-Entkopplung:</strong> Adaptive Applications dürfen den Watchdog niemals direkt bedienen. Die Watchdog-Bedienung erfolgt ausschließlich gekoppelt an die erfolgreiche Evaluierung durch das PHM.\n</li><li><strong>Timing &amp; Konfiguration:</strong> Das Ausführungsintervall des PHM-Loops, die Supervisions-Toleranzfenster und die Hardware-Watchdog-Timeout-Periode müssen strikt aufeinander abgestimmt werden:\n $$\\text{Watchdog-Timeout} &gt; \\text{PHM-Loop-Periode} + \\text{Worst-Case Execution Time (WCET)} + \\text{Jitter}$$\n</li><li><strong>Sicherheitsrelevanz (ISO 26262):</strong> <code>checkSupervisions()</code> bildet die funktionale Grundlage für programmablauf- und lebendigkeitsbezogene Sicherheitsziele (Safety Goals). Ein fehlerhaft konfiguriertes Überwachungsmodell im ARXML führt entweder zu unberechtigten System-Resets (<em>False Positives</em>) oder zum Ausbleiben der Fehlerreaktion (<em>False Negatives</em>).\n</li></ul>"}, {"id": "FIG-4bca87b097bec626", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsszenario mit Interaktionsrahmen <code>loop</code>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R23-11, Spezifikation <code>AUTOSAR_AP_EXP_SWArchitecture</code>, Kapitel 11 (Platform Health Management, PHM).\n</li><li><strong>Technischer Zweck:</strong> Darstellung des zyklischen Basismechanismus zur Überwachung der Plattform- und Applikationsintegrität sowie der abgeleiteten Watchdog-Bedienung. Das PHM dient als zentrale Instanz zur Bündelung aller Überwachungsergebnisse vor dem Hardware-/System-Watchdog-Trigger.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>«aapFunctionalCluster» :Platform Health Management</code>:</strong>\n<ul class=\"fig-list\"><li>Instanz des funktionalen Clusters PHM der Adaptive Platform.\n</li><li>Verantwortlich für die Aggregation und Auswertung aller konfigurierten Überwachungsarten (<em>Alive Supervision</em>, <em>Deadline Supervision</em>, <em>Logical Supervision</em>).\n</li></ul>\n</li><li><strong><code>:Watchdog</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrahierte Zielentität (z. B. Watchdog-Daemon, OS-Watchdog-Service oder Hardware-Watchdog-Treiber).\n</li></ul>\n</li><li><strong>Aufgerufene Operationen / Schnittstellen:</strong>\n<ul class=\"fig-list\"><li><code>«aapInformative» checkSupervisions()</code>: PHM-interne synchrone Methode (Self-Call), formal durch das Stereotyp <code>«aapInformative»</code> als rein informatives Modellelement annotiert, zur periodischen Auswertung aller aktiven Überwachungsmetriken und Checkpoint-Zustände.\n</li><li><code>AliveNotification()</code>: Ausgehender Methodenaufruf vom PHM an den Watchdog zur Bestätigung der Systemlebensfähigkeit (<em>Watchdog Refresh / Kick</em>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Zyklus (<code>loop</code>-Block):</strong> Läuft deterministisch in einer Endlosschleife, getaktet durch die konfigurierte Zykluszeit der PHM-Hauptverarbeitungsaufgabe.\n</li></ul>\n<ol class=\"fig-list\"><li><strong>Zustandsevaluierung:</strong> Das PHM führt intern <code>checkSupervisions()</code> aus. Hierbei werden alle empfangenen Checkpoint-Meldungen, Alive-Zähler, Ausführungsreihenfolgen und Latenzzeiten der überwachten Prozesse gegen die im Manifest hinterlegten Schwellwerte validiert.\n</li><li><strong>Watchdog-Triggern:</strong> Bei intaktem Gesamtzustand (<em>Supervision Status: OK</em>) setzt das PHM den Aufruf <code>AliveNotification()</code> an die Entität <code>:Watchdog</code> ab, um einen Timeout/Reset des Watchdogs zu verhindern.\n</li></ol>\n<ul class=\"fig-list\"><li><strong>Fehlerpfad (implizit/Abbruchbedingung):</strong> Ergibt <code>checkSupervisions()</code> einen unzulässigen Status (z. B. Deadline-Verletzung, Alive-Counter-Diskrepanz) und greift keine rein lokale Recovery Action, wird <code>AliveNotification()</code> unterdrückt. Dies führt zum gezielten Ablauf des Watchdogs und initiiert den plattformweiten Hardware-/System-Reset.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Architektur-Entkopplung:</strong> Adaptive Applications dürfen den Watchdog niemals direkt bedienen. Die Watchdog-Bedienung erfolgt ausschließlich gekoppelt an die erfolgreiche Evaluierung durch das PHM.\n</li><li><strong>Timing &amp; Konfiguration:</strong> Das Ausführungsintervall des PHM-Loops, die Supervisions-Toleranzfenster und die Hardware-Watchdog-Timeout-Periode müssen strikt aufeinander abgestimmt werden:\n $$\\text{Watchdog-Timeout} &gt; \\text{PHM-Loop-Periode} + \\text{Worst-Case Execution Time (WCET)} + \\text{Jitter}$$\n</li><li><strong>Sicherheitsrelevanz (ISO 26262):</strong> <code>checkSupervisions()</code> bildet die funktionale Grundlage für programmablauf- und lebendigkeitsbezogene Sicherheitsziele (Safety Goals). Ein fehlerhaft konfiguriertes Überwachungsmodell im ARXML führt entweder zu unberechtigten System-Resets (<em>False Positives</em>) oder zum Ausbleiben der Fehlerreaktion (<em>False Negatives</em>).\n</li></ul>"}, {"id": "FIG-3814eae3ce11a8e3", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsszenario mit Interaktionsrahmen <code>loop</code>).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R23-11, Spezifikation <code>AUTOSAR_AP_EXP_SWArchitecture</code>, Kapitel 11 (Platform Health Management, PHM).\n</li><li><strong>Technischer Zweck:</strong> Darstellung des zyklischen Basismechanismus zur Überwachung der Plattform- und Applikationsintegrität sowie der abgeleiteten Watchdog-Bedienung. Das PHM dient als zentrale Instanz zur Bündelung aller Überwachungsergebnisse vor dem Hardware-/System-Watchdog-Trigger.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>«aapFunctionalCluster» :Platform Health Management</code>:</strong>\n<ul class=\"fig-list\"><li>Instanz des funktionalen Clusters PHM der Adaptive Platform.\n</li><li>Verantwortlich für die Aggregation und Auswertung aller konfigurierten Überwachungsarten (<em>Alive Supervision</em>, <em>Deadline Supervision</em>, <em>Logical Supervision</em>).\n</li></ul>\n</li><li><strong><code>:Watchdog</code>:</strong>\n<ul class=\"fig-list\"><li>Abstrahierte Zielentität (z. B. Watchdog-Daemon, OS-Watchdog-Service oder Hardware-Watchdog-Treiber).\n</li></ul>\n</li><li><strong>Aufgerufene Operationen / Schnittstellen:</strong>\n<ul class=\"fig-list\"><li><code>«aapInformative» checkSupervisions()</code>: PHM-interne synchrone Methode (Self-Call), formal durch das Stereotyp <code>«aapInformative»</code> als rein informatives Modellelement annotiert, zur periodischen Auswertung aller aktiven Überwachungsmetriken und Checkpoint-Zustände.\n</li><li><code>AliveNotification()</code>: Ausgehender Methodenaufruf vom PHM an den Watchdog zur Bestätigung der Systemlebensfähigkeit (<em>Watchdog Refresh / Kick</em>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Zyklus (<code>loop</code>-Block):</strong> Läuft deterministisch in einer Endlosschleife, getaktet durch die konfigurierte Zykluszeit der PHM-Hauptverarbeitungsaufgabe.\n</li></ul>\n<ol class=\"fig-list\"><li><strong>Zustandsevaluierung:</strong> Das PHM führt intern <code>checkSupervisions()</code> aus. Hierbei werden alle empfangenen Checkpoint-Meldungen, Alive-Zähler, Ausführungsreihenfolgen und Latenzzeiten der überwachten Prozesse gegen die im Manifest hinterlegten Schwellwerte validiert.\n</li><li><strong>Watchdog-Triggern:</strong> Bei intaktem Gesamtzustand (<em>Supervision Status: OK</em>) setzt das PHM den Aufruf <code>AliveNotification()</code> an die Entität <code>:Watchdog</code> ab, um einen Timeout/Reset des Watchdogs zu verhindern.\n</li></ol>\n<ul class=\"fig-list\"><li><strong>Fehlerpfad (implizit/Abbruchbedingung):</strong> Ergibt <code>checkSupervisions()</code> einen unzulässigen Status (z. B. Deadline-Verletzung, Alive-Counter-Diskrepanz) und greift keine rein lokale Recovery Action, wird <code>AliveNotification()</code> unterdrückt. Dies führt zum gezielten Ablauf des Watchdogs und initiiert den plattformweiten Hardware-/System-Reset.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Architektur-Entkopplung:</strong> Adaptive Applications dürfen den Watchdog niemals direkt bedienen. Die Watchdog-Bedienung erfolgt ausschließlich gekoppelt an die erfolgreiche Evaluierung durch das PHM.\n</li><li><strong>Timing &amp; Konfiguration:</strong> Das Ausführungsintervall des PHM-Loops, die Supervisions-Toleranzfenster und die Hardware-Watchdog-Timeout-Periode müssen strikt aufeinander abgestimmt werden:\n $$\\text{Watchdog-Timeout} &gt; \\text{PHM-Loop-Periode} + \\text{Worst-Case Execution Time (WCET)} + \\text{Jitter}$$\n</li><li><strong>Sicherheitsrelevanz (ISO 26262):</strong> <code>checkSupervisions()</code> bildet die funktionale Grundlage für programmablauf- und lebendigkeitsbezogene Sicherheitsziele (Safety Goals). Ein fehlerhaft konfiguriertes Überwachungsmodell im ARXML führt entweder zu unberechtigten System-Resets (<em>False Positives</em>) oder zum Ausbleiben der Fehlerreaktion (<em>False Negatives</em>).\n</li></ul>"}], "trans": [{"from": "FIG-442e2fefebc19b75", "to": "FIG-4bca87b097bec626", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Interne Methode <code>checkSupervisions()</code>: Ergänzung des Stereotyps <code>«aapInformative»</code> oberhalb des Methodenaufrufs zur formalen Kennzeichnung als informatives Modellelement.\n</li></ul>"}, {"from": "FIG-4bca87b097bec626", "to": "FIG-3814eae3ce11a8e3", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
